// Native scalar stages: ATLAS interval compilation, PACK image construction
// and TRACE packed lookup over actual FIDX version 2 image bytes.
#include "engine.hpp"

#include <cstdio>
#include <cstdlib>
#include <iostream>
#include <iterator>
#include <string>
#include <vector>

namespace {

class Scanner {
public:
    explicit Scanner(const std::string& text)
        : cursor_(text.data()), end_(text.data() + text.size()) {}

    bool token(std::string& out) {
        while (cursor_ < end_ && (unsigned char)*cursor_ <= ' ') ++cursor_;
        if (cursor_ >= end_) return false;
        const char* start = cursor_;
        while (cursor_ < end_ && (unsigned char)*cursor_ > ' ') ++cursor_;
        out.assign(start, cursor_);
        return true;
    }

    std::string need_token() {
        std::string value;
        if (!token(value)) throw std::runtime_error("truncated native input");
        return value;
    }

    long long need_int() {
        std::string text = need_token();
        const char* begin = text.c_str();
        char* stop = nullptr;
        long long value = strtoll(begin, &stop, 10);
        if (stop == begin || (stop && *stop)) throw std::runtime_error("native integer");
        return value;
    }

    size_t need_size() {
        long long value = need_int();
        if (value < 0) throw std::runtime_error("native count");
        return (size_t)value;
    }

    int need_hop() {
        long long value = need_int();
        return (int)value;
    }

private:
    const char* cursor_;
    const char* end_;
};

inline void append_number(std::string& out, long long value) {
    char buffer[32];
    int length = snprintf(buffer, sizeof(buffer), "%lld", value);
    out.append(buffer, (size_t)length);
}

inline void append_row(std::string& out, const Answer& answer) {
    append_number(out, answer.hop);
    out.push_back(' ');
    append_number(out, answer.run);
    out.push_back(' ');
    append_number(out, (long long)answer.path.size());
    for (u32 offset : answer.path) {
        out.push_back(' ');
        append_number(out, (long long)offset);
    }
    out.push_back('\n');
}

void stage_atlas(Scanner& scanner, std::string& out) {
    size_t n = scanner.need_size();
    std::vector<Route> fib;
    fib.reserve(n);
    for (size_t i = 0; i < n; ++i) {
        std::string start = scanner.need_token();
        int length = (int)scanner.need_int();
        int hop = scanner.need_hop();
        fib.push_back({key(start), length, hop});
    }
    std::vector<std::pair<Key, int>> runs = atlas_runs(fib);
    append_number(out, (long long)runs.size());
    out.push_back('\n');
    for (const auto& run : runs) {
        out += hexkey(run.first);
        out.push_back(' ');
        append_number(out, run.second);
        out.push_back('\n');
    }
}

void stage_pack(Scanner& scanner, std::string& out) {
    size_t R = scanner.need_size();
    size_t N = scanner.need_size();
    size_t A = scanner.need_size();
    std::vector<Key> starts;
    std::vector<int> hops;
    starts.reserve(R);
    hops.reserve(R);
    for (size_t i = 0; i < R; ++i) {
        starts.push_back(key(scanner.need_token()));
        hops.push_back(scanner.need_hop());
    }
    std::vector<Layout> layout;
    layout.reserve(N);
    for (size_t i = 0; i < N; ++i) {
        Layout node;
        node.lo = (int)scanner.need_int();
        node.span = (int)scanner.need_int();
        node.mode = (int)scanner.need_int();
        node.cached = (int)scanner.need_int();
        size_t children = scanner.need_size();
        node.children.reserve(children);
        for (size_t c = 0; c < children; ++c) node.children.push_back((int)scanner.need_int());
        layout.push_back(std::move(node));
    }
    std::vector<Key> addresses;
    addresses.reserve(A);
    for (size_t i = 0; i < A; ++i) addresses.push_back(key(scanner.need_token()));
    std::vector<u8> raw = pack_bytes(starts, hops, layout);
    out += image_hex(raw);
    out.push_back('\n');
    Img image = decode_image(raw);
    for (const Answer& answer : search(image, addresses)) append_row(out, answer);
}

void stage_trace(Scanner& scanner, std::string& out) {
    size_t A = scanner.need_size();
    std::vector<u8> raw = unhex(scanner.need_token());
    std::vector<Key> addresses;
    addresses.reserve(A);
    for (size_t i = 0; i < A; ++i) addresses.push_back(key(scanner.need_token()));
    Img image = decode_image(raw);
    for (const Answer& answer : search(image, addresses)) append_row(out, answer);
}

}  // namespace

int main() {
    std::ios::sync_with_stdio(false);
    try {
        std::string input((std::istreambuf_iterator<char>(std::cin)),
                          std::istreambuf_iterator<char>());
        Scanner scanner(input);
        std::string command;
        if (!scanner.token(command)) return 0;
        std::string out;
        out.reserve(1 << 16);
        if (command == "ATLAS") stage_atlas(scanner, out);
        else if (command == "PACK") stage_pack(scanner, out);
        else if (command == "TRACE") stage_trace(scanner, out);
        else throw std::runtime_error("unknown native command");
        std::fwrite(out.data(), 1, out.size(), stdout);
        std::fflush(stdout);
        return 0;
    } catch (const std::exception& error) {
        std::fprintf(stderr, "%s\n", error.what());
        return 1;
    }
}
